/* Real torn-edge masks from rip-1.png (design assets). Data URLs because CSS mask fetches are CORS-gated. */
.rip-r40 { mask-image: url("data:image/png;base64,"), linear-gradient(#000,#000); mask-size: 40px 100%, calc(100% - 38px) 100%; mask-position: right center, left center; mask-repeat: no-repeat, no-repeat; }
.rip-l34 { mask-image: url("data:image/png;base64,"), linear-gradient(#000,#000); mask-size: 34px 100%, calc(100% - 32px) 100%; mask-position: left center, right center; mask-repeat: no-repeat, no-repeat; }
.rip-b70 { mask-image: url("data:image/png;base64,"), linear-gradient(#000,#000); mask-size: 100% 70px, 100% calc(100% - 68px); mask-position: bottom center, top center; mask-repeat: no-repeat, no-repeat; }
.rip-t60 { mask-image: url("data:image/png;base64,"), linear-gradient(#000,#000); mask-size: 100% 60px, 100% calc(100% - 58px); mask-position: top center, bottom center; mask-repeat: no-repeat, no-repeat; }
.tk-hard { mask-image: radial-gradient(circle at 138px 6px, #000 2.4px, transparent 3px), url("data:image/png;base64,"), linear-gradient(#000,#000); mask-size: 100% 12px, 46px 100%, calc(100% - 44px) 100%; mask-position: 0 0, right center, left center; mask-repeat: repeat-y, no-repeat, no-repeat; mask-composite: exclude, add, add; }

/* Ink dropout: photocopy luminance as alpha so printed type breaks up like thermal/offset ink on card stock. */
.ink-worn { mask-image: url("data:image/png;base64,"); mask-size: 520px auto; mask-repeat: repeat; }
.ink-worn-2 { mask-image: url("data:image/png;base64,"); mask-size: 380px auto; mask-position: 40% 60%; mask-repeat: repeat; }
